const SLOTS=[{id:1,name:"Frühstück"},{id:2,name:"Mittag"},{id:3,name:"Abend"}];
const ALLERGEN_LABELS={
  gluten:{de:"Glutenhaltiges Getreide",en:"Cereals containing gluten"},crustaceans:{de:"Krebstiere",en:"Crustaceans"},eggs:{de:"Eier",en:"Eggs"},fish:{de:"Fisch",en:"Fish"},peanuts:{de:"Erdnüsse",en:"Peanuts"},soy:{de:"Soja",en:"Soy"},milk:{de:"Milch",en:"Milk"},nuts:{de:"Schalenfrüchte",en:"Tree nuts"},celery:{de:"Sellerie",en:"Celery"},mustard:{de:"Senf",en:"Mustard"},sesame:{de:"Sesam",en:"Sesame"},sulphites:{de:"Schwefeldioxid / Sulfite",en:"Sulphur dioxide / sulphites"},lupin:{de:"Lupinen",en:"Lupin"},molluscs:{de:"Weichtiere",en:"Molluscs"}
};
const DIETS=[{code:"vegetarian",de:"Vegetarisch",en:"Vegetarian"},{code:"vegan",de:"Vegan",en:"Vegan"},{code:"pescetarian",de:"Pescetarisch",en:"Pescetarian"},{code:"no_pork",de:"Kein Schweinefleisch",en:"No pork"}];
const TXT={
  de:{home:"Start",recipes:"Rezepte",roulette:"Roulette",plan:"Wochenplan",shopping:"Einkauf",pantry:"Vorrat",rescue:"Food Rescue",login:"Anmelden",logout:"Abmelden",profile:"Profil",foodProfile:"Ernährung & Allergien",household:"Haushalt",security:"Sicherheit",close:"Schließen",save:"Speichern",cancel:"Abbrechen",loading:"Wird geladen …",error:"Etwas ist schiefgelaufen.",noRecipes:"Keine Rezepte gefunden.",open:"Öffnen",favorite:"Favorit",planIt:"Einplanen",eaten:"Gegessen",cook:"Kochmodus",servings:"Portionen",ingredients:"Zutaten",instructions:"Zubereitung",rating:"Deine Bewertung",allergens:"Allergene",allergyNotice:"Allergenangaben werden aus den hinterlegten Rezeptzutaten abgeleitet. Bei Allergien bitte zusätzlich immer die Kennzeichnung der tatsächlich verwendeten Produkte prüfen.",personal:"Für mich",householdScope:"Haushalt",install:"App installieren",installText:"Rezeptroulette direkt vom Startbildschirm öffnen – wie eine App.",signInRequired:"Bitte melde dich an, um diese Funktion zu verwenden.",copy:"Liste kopieren",copied:"Kopiert.",saved:"Gespeichert.",back:"Zurück",next:"Weiter",empty:"Noch leer",createAccount:"Konto erstellen",username:"Benutzername",displayName:"Anzeigename",email:"E-Mail",password:"Passwort",currentPassword:"Aktuelles Passwort",newPassword:"Neues Passwort",bio:"Profilbeschreibung",createHousehold:"Haushalt erstellen",joinHousehold:"Haushalt beitreten",inviteCode:"Einladungscode",leaveHousehold:"Haushalt verlassen",exportData:"Daten exportieren",deleteAccount:"Konto löschen",logoutAll:"Auf allen Geräten abmelden",sessions:"Aktive Sitzungen"},
  en:{home:"Home",recipes:"Recipes",roulette:"Roulette",plan:"Meal plan",shopping:"Shopping",pantry:"Pantry",rescue:"Food Rescue",login:"Sign in",logout:"Sign out",profile:"Profile",foodProfile:"Diet & allergies",household:"Household",security:"Security",close:"Close",save:"Save",cancel:"Cancel",loading:"Loading …",error:"Something went wrong.",noRecipes:"No recipes found.",open:"Open",favorite:"Favorite",planIt:"Add to plan",eaten:"Eaten",cook:"Cooking mode",servings:"Servings",ingredients:"Ingredients",instructions:"Instructions",rating:"Your rating",allergens:"Allergens",allergyNotice:"Allergen information is derived from the recipe ingredients stored in the app. If you have allergies, always check the labels of the products you actually use as well.",personal:"For me",householdScope:"Household",install:"Install app",installText:"Open Rezeptroulette right from your home screen – like an app.",signInRequired:"Please sign in to use this feature.",copy:"Copy list",copied:"Copied.",saved:"Saved.",back:"Back",next:"Next",empty:"Empty",createAccount:"Create account",username:"Username",displayName:"Display name",email:"Email",password:"Password",currentPassword:"Current password",newPassword:"New password",bio:"Profile description",createHousehold:"Create household",joinHousehold:"Join household",inviteCode:"Invite code",leaveHousehold:"Leave household",exportData:"Export data",deleteAccount:"Delete account",logoutAll:"Sign out on all devices",sessions:"Active sessions"}
};
const state={user:null,recipes:[],favorites:[],ratings:{},eaten:[],foodProfile:null,allergens:Object.keys(ALLERGEN_LABELS),household:null,pantry:[],scope:localStorage.getItem("rr_scope")||"personal",lang:localStorage.getItem("rr_lang")||"de",view:"home",installPrompt:null,cookSteps:[],cookIndex:0};
if(!["de","en"].includes(state.lang))state.lang="de";
if(!["personal","household"].includes(state.scope))state.scope="personal";
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const t=k=>TXT[state.lang]?.[k]||TXT.de[k]||k;
const esc=v=>String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[c]);
const qs=o=>Object.entries(o).filter(([,v])=>v!==undefined&&v!==null&&v!=="").map(([k,v])=>`${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join("&");
function toast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toast._timer);toast._timer=setTimeout(()=>el.classList.remove("show"),2600)}
function errorMessage(data,status){if(typeof data?.detail==="string")return data.detail;if(Array.isArray(data?.detail))return data.detail.map(x=>x.msg).join("; ");return `${t("error")} (${status})`}
async function api(path,options={}){const opts={credentials:"same-origin",...options};if(opts.body&&!(opts.body instanceof FormData)){opts.headers={"Content-Type":"application/json",...(opts.headers||{})}}const r=await fetch(path,opts);let data=null;const type=r.headers.get("content-type")||"";if(type.includes("application/json")){try{data=await r.json()}catch{}}else{try{data=await r.text()}catch{}}if(!r.ok){const err=new Error(errorMessage(data,r.status));err.status=r.status;err.data=data;throw err}return data}
function normalizeList(v){if(Array.isArray(v))return v;if(Array.isArray(v?.items))return v.items;if(Array.isArray(v?.ids))return v.ids;return []}
function imageUrl(r){const v=String(r?.bild||"").trim();if(!v)return "";if(/^https?:\/\//i.test(v)||v.startsWith("/"))return v;return `/bilder/${encodeURIComponent(v)}`}
function imgMarkup(r,cls=""){const url=imageUrl(r);return url?`<img class="${cls}" src="${esc(url)}" alt="${esc(r.name||"")}" loading="lazy" onerror="this.replaceWith(Object.assign(document.createElement('div'),{className:'placeholder',textContent:'🍽️'}))">`:`<div class="placeholder">🍽️</div>`}
function allergenName(code){return ALLERGEN_LABELS[code]?.[state.lang]||code}
function allergenBadges(r){return (r.allergens||[]).map(code=>`<span class="pill allergen-pill">⚠ ${esc(allergenName(code))}</span>`).join("")}
function recipeConflicts(r){const mine=new Set(state.foodProfile?.allergies||[]);return (r.allergens||[]).filter(x=>mine.has(x))}
function scopeParam(){return state.user?state.scope:"personal"}
function setScope(scope,rerender=true){if(scope==="household"&&!state.household){toast(state.lang==="de"?"Erstelle oder tritt zuerst einem Haushalt bei.":"Create or join a household first.");return}state.scope=scope;localStorage.setItem("rr_scope",scope);if(rerender)renderCurrent()}
function scopeSwitch(){if(!state.user)return "";return `<div class="scope-switch"><button class="${state.scope==="personal"?"active":""}" onclick="setScope('personal')">${t("personal")}</button><button class="${state.scope==="household"?"active":""}" onclick="setScope('household')">${t("householdScope")}</button></div>`}
function loading(){return `<div class="empty">${t("loading")}</div>`}
function setView(view){state.view=view;$$('[data-nav]').forEach(b=>b.classList.toggle("active",b.dataset.nav===view));window.scrollTo({top:0,behavior:"smooth"});setTimeout(()=>$("#main")?.focus(),0)}
function route(view){setView(view);({home:renderHome,recipes:renderRecipes,roulette:renderRoulette,plan:renderPlan,shopping:renderShopping,pantry:renderPantry,rescue:renderRescue}[view]||renderHome)()}
function renderCurrent(){route(state.view)}
function updateChrome(){document.documentElement.lang=state.lang;$("#languageBtn").textContent=state.lang.toUpperCase();$("#themeBtn").textContent=document.body.classList.contains("dark")?"☀️":"🌙";$("#accountBtn").textContent=state.user?(state.user.display_name||state.user.username):t("login");const navKeys={home:"home",recipes:"recipes",roulette:"roulette",plan:"plan",shopping:"shopping",pantry:"pantry",rescue:"rescue"};Object.entries(navKeys).forEach(([key,label])=>$$(`[data-nav="${key}"]`).forEach(el=>{if(el.closest('.bottom-nav')){const small=el.querySelector('small');if(small)small.textContent=t(label)}else el.textContent=t(label)}))}
async function refreshRecipes(){state.recipes=await api(`/rezepte?t=${Date.now()}`);return state.recipes}
async function loadAccountState(){if(!state.user)return;const tasks=[api("/favorites").catch(()=>[]),api("/ratings").catch(()=>({})),api("/eaten").catch(()=>[]),api("/profile/food").catch(()=>null),api("/household").catch(()=>null)];const [fav,ratings,eaten,food,house]=await Promise.all(tasks);state.favorites=normalizeList(fav).map(Number);state.ratings=ratings?.ratings||ratings||{};state.eaten=normalizeList(eaten);if(food){state.foodProfile=food.profile||{};state.allergens=food.available_allergens||state.allergens}state.household=house?.household===undefined?house:house.household;if(!state.household&&state.scope==="household")state.scope="personal";await loadPantry().catch(()=>{})}
async function initAuth(){try{state.user=await api("/auth/me");await loadAccountState()}catch(e){if(e.status!==401)console.warn(e);state.user=null;state.foodProfile=null;state.household=null}}
function isFav(id){return state.favorites.includes(Number(id))}
function recipeCard(r){const conflicts=recipeConflicts(r);return `<article class="card"><div class="card-media" onclick="openRecipe(${Number(r.id)})">${imgMarkup(r)}</div><div class="card-body"><div class="card-title">${esc(r.name)}</div><p class="card-desc">${esc(r.description||"")}</p><div class="meta"><span class="pill">⏱ ${Number(r.kochzeit)||"?"} Min</span><span class="pill">🍽 ${Number(r.portionen)||2}</span><span class="pill">${esc(r.schwierigkeit||"")}</span></div>${r.allergens?.length?`<div class="meta" style="margin-top:8px">${allergenBadges(r)}</div>`:""}${conflicts.length?`<div class="safe-note blocked" style="margin-top:9px">${state.lang==="de"?"Passt nicht zu deinem Allergieprofil.":"Conflicts with your allergy profile."}</div>`:""}<div class="button-row" style="margin-top:13px"><button class="primary" onclick="openRecipe(${Number(r.id)})">${t("open")}</button><button class="secondary" onclick="toggleFavorite(${Number(r.id)},event)">${isFav(r.id)?"❤️":"🤍"}</button></div></div></article>`}
async function safeRecommendations(count=3){const rows=[];if(state.user){for(let i=0;i<count;i++){try{const r=await api(`/roulette?${qs({scope:scopeParam(),avoid_recent:true})}`);if(r&&!rows.some(x=>Number(x.id)===Number(r.id)))rows.push(r)}catch{break}}}if(rows.length<count){const pool=state.recipes.filter(r=>!recipeConflicts(r).length);for(const r of [...pool].sort(()=>Math.random()-.5)){if(!rows.some(x=>Number(x.id)===Number(r.id)))rows.push(r);if(rows.length>=count)break}}return rows.slice(0,count)}
async function renderHome(){setView("home");$("#main").innerHTML=loading();if(!state.recipes.length)await refreshRecipes().catch(()=>{});const recs=await safeRecommendations(3);$("#main").innerHTML=`${installBanner()}<section class="hero"><div class="hero-main"><span class="eyebrow">${state.lang==="de"?"Schnell entscheiden. Besser planen.":"Decide quickly. Plan better."}</span><h1>${state.lang==="de"?"Was darf heute auf den Tisch?":"What’s for dinner today?"}</h1><p class="lead">${state.lang==="de"?"Rezeptroulette berücksichtigt dein Profil, deine Vorräte und auf Wunsch deinen Haushalt – und nimmt dir die Essensentscheidung ab.":"Rezeptroulette considers your profile, pantry and household when you want it to – and takes the meal decision off your plate."}</p><div class="button-row"><button class="primary" onclick="route('roulette')">🎲 ${state.lang==="de"?"Rezept ziehen":"Pick a recipe"}</button><button class="secondary" onclick="route('recipes')">🍲 ${t("recipes")}</button></div></div><div class="hero-side"><button class="quick-card" onclick="route('plan')"><span class="qicon">📅</span><span><strong>${t("plan")}</strong><small>${state.lang==="de"?"Automatisch oder manuell planen":"Plan automatically or manually"}</small></span><span>→</span></button><button class="quick-card" onclick="route('shopping')"><span class="qicon">🛒</span><span><strong>${t("shopping")}</strong><small>${state.lang==="de"?"Gleiche Lebensmittel intelligent bündeln":"Smartly combine identical foods"}</small></span><span>→</span></button><button class="quick-card" onclick="route('pantry')"><span class="qicon">🏠</span><span><strong>${t("pantry")}</strong><small>${state.lang==="de"?"Mengen und Haltbarkeit verwalten":"Track amounts and expiry dates"}</small></span><span>→</span></button><button class="quick-card" onclick="route('rescue')"><span class="qicon">♻️</span><span><strong>Food Rescue</strong><small>${state.lang==="de"?"Verwerte, was bald weg muss":"Use what needs eating soon"}</small></span><span>→</span></button></div></section><section class="section"><div class="section-head"><div><h2>${state.lang==="de"?"Heute passend":"A good fit today"}</h2><p class="muted">${state.lang==="de"?"Vorschläge unter Berücksichtigung deiner Einstellungen.":"Suggestions based on your settings."}</p></div>${scopeSwitch()}</div><div class="recipe-grid">${recs.length?recs.map(recipeCard).join(""):`<div class="empty">${t("noRecipes")}</div>`}</div></section>`}
function installBanner(){if(!(state.installPrompt||isIOS()))return "";return `<div class="install-banner show"><div><strong>${t("install")}</strong><div class="hint">${t("installText")}</div></div><button class="primary" onclick="installApp()">${t("install")}</button></div>`}
const CATS=["Alle","Frühstück","Vegetarisch","Vegan","Nudeln","Reis","Auflauf","Suppe","Dessert"];
async function renderRecipes(){setView("recipes");$("#main").innerHTML=loading();await refreshRecipes().catch(e=>toast(e.message));$("#main").innerHTML=`<div class="section-head"><div><span class="eyebrow">${state.lang==="de"?"Rezeptbibliothek":"Recipe library"}</span><h2>${t("recipes")}</h2><p class="muted">${state.lang==="de"?"Suche, filtere und öffne deine Rezepte.":"Search, filter and open your recipes."}</p></div>${state.user?`<button class="secondary" onclick="openCreateRecipe()">＋ ${state.lang==="de"?"Eigenes Rezept":"My recipe"}</button>`:""}</div><div class="filters"><input id="recipeSearch" placeholder="${state.lang==="de"?"Rezept oder Zutat suchen …":"Search recipe or ingredient …"}" oninput="filterRecipes()"><select id="recipeCat" onchange="filterRecipes()">${CATS.map(x=>`<option>${x}</option>`).join("")}</select><select id="recipeTime" onchange="filterRecipes()"><option value="0">${state.lang==="de"?"Beliebige Zeit":"Any time"}</option><option value="20">≤ 20 Min</option><option value="30">≤ 30 Min</option><option value="45">≤ 45 Min</option><option value="60">≤ 60 Min</option></select><select id="recipeSort" onchange="filterRecipes()"><option value="name">A–Z</option><option value="time">${state.lang==="de"?"Kochzeit":"Cooking time"}</option><option value="rating">${t("rating")}</option></select></div><div id="recipeCount" class="hint" style="margin-bottom:10px"></div><div id="recipeGrid" class="recipe-grid"></div>`;filterRecipes()}
function categoryMatch(r,cat){if(!cat||cat==="Alle")return true;const text=[r.name,r.kueche,r.description,r.anleitung,...(r.tags||[]),...(r.zutaten||[])].join(" ").toLowerCase();const c=cat.toLowerCase();if(c==="frühstück")return /frühstück|breakfast|pancake|oats|porridge|omelett/.test(text);if(c==="vegetarisch")return /vegetar|veggie/.test(text);if(c==="vegan")return /vegan/.test(text);if(c==="nudeln")return /nudel|pasta|spaghetti|tortellini|gnocchi/.test(text);if(c==="reis")return /\breis\b|rice/.test(text);if(c==="auflauf")return /auflauf|gratin|casserole/.test(text);if(c==="suppe")return /suppe|eintopf|soup/.test(text);if(c==="dessert")return /dessert|kuchen|pudding|tiramisu|süß/.test(text);return text.includes(c)}
function filterRecipes(){const q=($("#recipeSearch")?.value||"").trim().toLowerCase(),cat=$("#recipeCat")?.value||"Alle",max=Number($("#recipeTime")?.value||0),sort=$("#recipeSort")?.value||"name";let rows=state.recipes.filter(r=>{const text=[r.name,r.kueche,r.description,...(r.tags||[]),...(r.zutaten||[])].join(" ").toLowerCase();return(!q||text.includes(q))&&categoryMatch(r,cat)&&(!max||Number(r.kochzeit)<=max)});rows.sort((a,b)=>sort==="time"?Number(a.kochzeit)-Number(b.kochzeit):sort==="rating"?Number(state.ratings[b.id]||0)-Number(state.ratings[a.id]||0):String(a.name).localeCompare(String(b.name),state.lang));$("#recipeCount").textContent=`${rows.length} ${state.lang==="de"?"Rezepte":"recipes"}`;$("#recipeGrid").innerHTML=rows.length?rows.map(recipeCard).join(""):`<div class="empty">${t("noRecipes")}</div>`}
async function openRecipe(id,portions=null){setView("recipes");$("#main").innerHTML=loading();let r=null;try{r=portions?await api(`/rezepte/${id}/scale?portions=${Number(portions)}`):state.recipes.find(x=>Number(x.id)===Number(id));if(!r){await refreshRecipes();r=state.recipes.find(x=>Number(x.id)===Number(id))}}catch(e){toast(e.message)}if(!r)return $("#main").innerHTML=`<div class="empty">${t("noRecipes")}</div>`;state.currentRecipe=r;const ingredients=r.structured_ingredients?.length?r.structured_ingredients.map(x=>x.display||x.raw):(r.zutaten||[]);const steps=parseSteps(r.anleitung);const conflicts=recipeConflicts(r);let note="";if(state.user)try{const d=await api(`/recipe-notes/${id}`);note=d?.note||""}catch{}$("#main").innerHTML=`<div class="button-row" style="margin-bottom:13px"><button class="secondary" onclick="renderRecipes()">← ${t("back")}</button></div><section class="detail-hero"><div class="detail-image">${imgMarkup(r)}</div><aside class="detail-copy"><span class="eyebrow">${esc(r.kueche||t("recipes"))}</span><h1>${esc(r.name)}</h1><p class="lead">${esc(r.description||"")}</p><div class="meta"><span class="pill">⏱ ${Number(r.kochzeit)||"?"} Min</span><span class="pill">🔥 ${esc(r.schwierigkeit||"")}</span></div><label class="field" style="max-width:180px;margin-top:13px"><span>${t("servings")}</span><select onchange="openRecipe(${Number(id)},this.value)">${Array.from({length:10},(_,i)=>i+1).map(n=>`<option value="${n}" ${Number(r.requested_portions||r.portionen)===n?"selected":""}>${n}</option>`).join("")}</select></label>${r.allergens?.length?`<div style="margin-top:13px"><div class="hint">${t("allergens")}</div><div class="meta">${allergenBadges(r)}</div></div>`:""}${conflicts.length?`<div class="safe-note blocked" style="margin-top:13px"><strong>${state.lang==="de"?"Achtung":"Warning"}:</strong> ${state.lang==="de"?"Dieses Rezept widerspricht deinem gespeicherten Allergieprofil.":"This recipe conflicts with your saved allergy profile."}</div>`:""}<div class="safe-note" style="margin-top:13px">${esc(t("allergyNotice"))}</div><div class="button-row" style="margin-top:16px"><button class="primary" onclick="startCookMode(${Number(id)})">👨‍🍳 ${t("cook")}</button><button class="secondary" onclick="toggleFavorite(${Number(id)},event)">${isFav(id)?"❤️":"🤍"} ${t("favorite")}</button><button class="secondary" onclick="quickPlan(${Number(id)})">📅 ${t("planIt")}</button><button class="secondary" onclick="markEaten(${Number(id)})">✓ ${t("eaten")}</button></div><div style="margin-top:15px">${ratingMarkup(id)}</div></aside></section><section class="detail-columns"><div class="panel"><h2>${t("ingredients")}</h2><div class="ingredient-list">${ingredients.map(x=>`<div class="ingredient">✓ ${esc(x)}</div>`).join("")}</div>${state.user?`<div class="field" style="margin-top:16px"><span>${state.lang==="de"?"Private Notiz":"Private note"}</span><textarea id="recipeNote" maxlength="1200">${esc(note)}</textarea><button class="secondary" style="margin-top:7px" onclick="saveRecipeNote(${Number(id)})">${t("save")}</button></div>`:""}</div><div class="panel"><h2>${t("instructions")}</h2><div class="steps">${steps.map((s,i)=>`<div class="step"><span class="step-num">${i+1}</span><span>${esc(s)}</span></div>`).join("")}</div></div></section>`}
function parseSteps(v){return String(v||"").replaceAll("\\n","\n").split(/\n|(?=\d+\.\s)/).map(x=>x.replace(/^\d+\.\s*/,"").trim()).filter(Boolean)}
function ratingMarkup(id){const n=Number(state.ratings[id]||0);return `<div class="hint">${t("rating")}</div>${[1,2,3,4,5].map(i=>`<button class="star" onclick="setRating(${Number(id)},${i})">${i<=n?"★":"☆"}</button>`).join("")}`}
async function toggleFavorite(id,event){event?.stopPropagation();if(!state.user){toast(t("signInRequired"));return openAccount()}try{const d=await api(`/favorites/${id}/toggle`,{method:"POST"});state.favorites=normalizeList(d).map(Number);toast(t("saved"));if(state.view==="recipes"&&state.currentRecipe?.id==id)openRecipe(id,state.currentRecipe.requested_portions||null)}catch(e){toast(e.message)}}
async function setRating(id,rating){if(!state.user){toast(t("signInRequired"));return openAccount()}try{await api(`/ratings/${id}`,{method:"PUT",body:JSON.stringify({rating})});state.ratings[id]=rating;toast(t("saved"));openRecipe(id,state.currentRecipe?.requested_portions||null)}catch(e){toast(e.message)}}
async function markEaten(id){if(!state.user){toast(t("signInRequired"));return openAccount()}try{await api(`/eaten/${id}`,{method:"POST"});toast(t("saved"))}catch(e){toast(e.message)}}
async function saveRecipeNote(id){try{await api(`/recipe-notes/${id}`,{method:"PUT",body:JSON.stringify({note:$("#recipeNote").value})});toast(t("saved"))}catch(e){toast(e.message)}}
function startCookMode(id){const r=state.currentRecipe&&Number(state.currentRecipe.id)===Number(id)?state.currentRecipe:state.recipes.find(x=>Number(x.id)===Number(id));if(!r)return;state.cookSteps=parseSteps(r.anleitung);state.cookIndex=0;$("#cookTitle").textContent=r.name;$("#cookMode").classList.remove("hidden");renderCookStep();try{navigator.wakeLock?.request("screen").then(lock=>state.wakeLock=lock).catch(()=>{})}catch{}}
function renderCookStep(){const total=state.cookSteps.length;$("#cookProgress").textContent=total?`${state.lang==="de"?"Schritt":"Step"} ${state.cookIndex+1} / ${total}`:"";$("#cookStep").textContent=total?state.cookSteps[state.cookIndex]:(state.lang==="de"?"Keine Schritte vorhanden.":"No steps available.");$("#cookPrev").disabled=state.cookIndex<=0;$("#cookNext").textContent=state.cookIndex>=total-1?(state.lang==="de"?"Fertig ✓":"Done ✓"):`${t("next")} →`}
function closeCook(){$("#cookMode").classList.add("hidden");try{state.wakeLock?.release()}catch{}state.wakeLock=null}
async function renderRoulette(){setView("roulette");$("#main").innerHTML=`<div class="section-head"><div><span class="eyebrow">🎲 ${t("roulette")}</span><h2>${state.lang==="de"?"Lass dich überraschen":"Let it surprise you"}</h2><p class="muted">${state.lang==="de"?"Bei angemeldeten Nutzern werden Allergieprofil, Vorräte und bisherige Nutzung automatisch berücksichtigt.":"For signed-in users, allergy profile, pantry and previous use are considered automatically."}</p></div>${scopeSwitch()}</div><div class="two-col"><aside class="panel"><div class="form-stack"><label class="field"><span>${state.lang==="de"?"Kategorie":"Category"}</span><select id="rouletteCat">${CATS.map(x=>`<option>${x}</option>`).join("")}</select></label><label class="field"><span>${state.lang==="de"?"Maximale Kochzeit":"Maximum cooking time"}</span><select id="rouletteTime"><option value="0">${state.lang==="de"?"Egal":"Any"}</option><option value="20">20 Min</option><option value="30">30 Min</option><option value="45">45 Min</option><option value="60">60 Min</option></select></label><label class="check-row"><input id="rouletteRecent" type="checkbox" checked><span>${state.lang==="de"?"Kürzlich gegessene Rezepte vermeiden":"Avoid recently eaten recipes"}</span></label><button class="primary" onclick="drawRoulette()">🎲 ${state.lang==="de"?"Rezept ziehen":"Pick a recipe"}</button></div></aside><div id="rouletteResult" class="empty">${state.lang==="de"?"Bereit für eine Idee?":"Ready for an idea?"}</div></div>`}
async function drawRoulette(){const el=$("#rouletteResult");el.innerHTML=loading();try{const params={category:$("#rouletteCat").value,max_time:Number($("#rouletteTime").value),avoid_recent:$("#rouletteRecent").checked,scope:scopeParam()};let r;if(state.user)r=await api(`/roulette?${qs(params)}`);else{if(!state.recipes.length)await refreshRecipes();let pool=state.recipes.filter(x=>categoryMatch(x,params.category)&&(!params.max_time||Number(x.kochzeit)<=params.max_time));r=pool[Math.floor(Math.random()*pool.length)]}if(!r)throw new Error(t("noRecipes"));el.className="roulette-result";el.innerHTML=`<div class="media">${imgMarkup(r)}</div><div class="copy"><span class="eyebrow">🎉 ${state.lang==="de"?"Dein Treffer":"Your pick"}</span><h2 style="margin-top:10px">${esc(r.name)}</h2><p class="muted">${esc(r.description||"")}</p><div class="meta"><span class="pill">⏱ ${Number(r.kochzeit)||"?"} Min</span>${allergenBadges(r)}</div><div class="button-row" style="margin-top:15px"><button class="primary" onclick="openRecipe(${Number(r.id)})">${t("open")}</button><button class="secondary" onclick="drawRoulette()">${state.lang==="de"?"Nochmal":"Again"}</button></div></div>`}catch(e){el.className="empty";el.textContent=e.message}}
async function renderPlan(){setView("plan");$("#main").innerHTML=loading();if(!state.recipes.length)await refreshRecipes().catch(()=>{});try{const plan=await api(`/wochenplan?${qs({scope:scopeParam(),t:Date.now()})}`);$("#main").innerHTML=`<div class="section-head"><div><span class="eyebrow">📅 ${t("plan")}</span><h2>${state.lang==="de"?"Deine Woche":"Your week"}</h2><p class="muted">${state.lang==="de"?"Automatisch passend planen oder einzelne Mahlzeiten austauschen.":"Plan automatically or replace individual meals."}</p></div><div class="button-row">${scopeSwitch()}${state.user?`<button class="primary" onclick="autoPlan()">✨ ${state.lang==="de"?"Automatisch planen":"Auto-plan"}</button>`:""}<button class="secondary" onclick="resetPlan()">${state.lang==="de"?"Woche leeren":"Clear week"}</button></div></div>${!state.user?`<div class="safe-note" style="margin-bottom:13px">${state.lang==="de"?"Im Gastmodus ist der Plan nicht kontogebunden. Melde dich an, damit Allergien und persönliche Einstellungen automatisch berücksichtigt werden.":"In guest mode the plan is not linked to an account. Sign in to apply allergies and personal preferences automatically."}</div>`:""}<div class="week-grid">${DAYS.map(day=>`<article class="day-card"><h3>${day}</h3>${SLOTS.map(slot=>planSlot(day,slot,plan)).join("")}</article>`).join("")}</div>`}catch(e){$("#main").innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function slotMatch(r,slot){const text=[r.name,...(r.tags||[])].join(" ").toLowerCase(),breakfast=/frühstück|breakfast|pancake|oats|porridge|omelett/.test(text),dessert=/dessert|kuchen|pudding|sweet/.test(text);return slot.id===1?breakfast:!breakfast&&!dessert}
function planSlot(day,slot,plan){const id=plan?.[day]?.[slot.id]??plan?.[day]?.[String(slot.id)]??null,r=state.recipes.find(x=>Number(x.id)===Number(id));const opts=state.recipes.filter(x=>slotMatch(x,slot)&&!recipeConflicts(x).length);return `<div class="slot"><div class="slot-label">${slot.name}</div>${r?`<strong>${esc(r.name)}</strong><div class="button-row" style="margin-top:7px"><button class="ghost" onclick="openRecipe(${Number(r.id)})">${t("open")}</button><button class="ghost" onclick="setPlanSlot('${day}',${slot.id},0)">✕</button></div>`:`<div class="hint">${t("empty")}</div>`}<select onchange="if(this.value)setPlanSlot('${day}',${slot.id},this.value)" style="margin-top:7px"><option value="">${r?(state.lang==="de"?"Ersetzen":"Replace"):(state.lang==="de"?"Auswählen":"Choose")}</option>${opts.map(x=>`<option value="${Number(x.id)}">${esc(x.name)}</option>`).join("")}</select></div>`}
async function setPlanSlot(day,slot,id){try{await api(`/wochenplan/${encodeURIComponent(day)}/${slot}/${Number(id)}?${qs({scope:scopeParam()})}`,{method:"POST"});renderPlan()}catch(e){toast(e.message)}}
async function autoPlan(){if(!state.user)return openAccount();try{await api(`/wochenplan/auto?${qs({scope:scopeParam()})}`,{method:"POST"});toast(state.lang==="de"?"Woche geplant.":"Week planned.");renderPlan()}catch(e){toast(e.message)}}
async function resetPlan(){if(!confirm(state.lang==="de"?"Wochenplan wirklich leeren?":"Clear the whole meal plan?"))return;try{await api(`/wochenplan/reset?${qs({scope:scopeParam()})}`,{method:"POST"});renderPlan()}catch(e){toast(e.message)}}
function quickPlan(id){showModal(`<h2>${t("planIt")}</h2><form class="form-stack" onsubmit="submitQuickPlan(event,${Number(id)})"><label class="field"><span>${state.lang==="de"?"Tag":"Day"}</span><select id="quickDay">${DAYS.map(x=>`<option>${x}</option>`).join("")}</select></label><label class="field"><span>${state.lang==="de"?"Mahlzeit":"Meal"}</span><select id="quickSlot">${SLOTS.map(x=>`<option value="${x.id}">${x.name}</option>`).join("")}</select></label>${state.user?scopeSwitch():""}<button class="primary">${t("planIt")}</button></form>`)}
async function submitQuickPlan(e,id){e.preventDefault();try{await api(`/wochenplan/${encodeURIComponent($("#quickDay").value)}/${Number($("#quickSlot").value)}/${id}?${qs({scope:scopeParam()})}`,{method:"POST"});hideModal();toast(t("saved"))}catch(err){toast(err.message)}}
async function renderShopping(){setView("shopping");$("#main").innerHTML=loading();try{const d=await api(`/einkaufsliste?${qs({scope:scopeParam(),t:Date.now()})}`),cats=d.categories||{};const checkKey=`rr_checks_${state.scope}`,checked=new Set(JSON.parse(localStorage.getItem(checkKey)||"[]"));$("#main").innerHTML=`<div class="section-head"><div><span class="eyebrow">🛒 ${t("shopping")}</span><h2>${state.lang==="de"?"Intelligente Einkaufsliste":"Smart shopping list"}</h2><p class="muted">${state.lang==="de"?"Gleiche Lebensmittel werden zusammengeführt; vorhandene Vorräte werden berücksichtigt.":"Identical foods are combined and pantry items are considered."}</p></div><div class="button-row">${scopeSwitch()}<button class="secondary" onclick="copyShopping()">${t("copy")}</button></div></div>${Object.keys(cats).length?Object.entries(cats).map(([cat,items])=>`<section class="panel" style="margin-bottom:12px"><h3>${esc(cat)}</h3><div class="shopping-list">${items.map(label=>{const key=`${cat}|${label}`;return `<label class="shopping-row ${checked.has(key)?"done":""}"><input type="checkbox" ${checked.has(key)?"checked":""} onchange="toggleShoppingCheck('${encodeURIComponent(key)}',this.checked,this.closest('.shopping-row'))"><span class="shopping-item-text">${esc(label)}</span></label>`}).join("")}</div></section>`).join(""):`<div class="empty">${state.lang==="de"?"Nichts einzukaufen. Plane zuerst Gerichte oder prüfe deinen Vorrat.":"Nothing to buy. Add meals to your plan or check your pantry."}</div>`} <div class="safe-note" style="margin-top:12px">${state.lang==="de"?"Abgehakte Positionen werden auf diesem Gerät gespeichert. Die Lebensmittelmengen selbst stammen aus deinem aktuellen Plan und Vorrat.":"Checked items are saved on this device. Food quantities come from your current plan and pantry."}</div>`}catch(e){$("#main").innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function toggleShoppingCheck(encoded,checked,row){const key=decodeURIComponent(encoded),storage=`rr_checks_${state.scope}`,set=new Set(JSON.parse(localStorage.getItem(storage)||"[]"));checked?set.add(key):set.delete(key);localStorage.setItem(storage,JSON.stringify([...set]));row.classList.toggle("done",checked)}
function copyShopping(){const rows=$$(".shopping-row:not(.done) .shopping-item-text").map(x=>x.textContent.trim());navigator.clipboard?.writeText(rows.join("\n")).then(()=>toast(t("copied"))).catch(()=>toast(t("error")))}
async function loadPantry(){if(!state.user){state.pantry=JSON.parse(localStorage.getItem("rr_guest_pantry")||"[]");return state.pantry}const d=await api(`/pantry-v2?${qs({scope:scopeParam()})}`);state.pantry=d?.items||[];return state.pantry}
async function renderPantry(){setView("pantry");$("#main").innerHTML=loading();try{await loadPantry();$("#main").innerHTML=`<div class="section-head"><div><span class="eyebrow">🏠 ${t("pantry")}</span><h2>${state.lang==="de"?"Was ist schon da?":"What do you already have?"}</h2><p class="muted">${state.lang==="de"?"Mengen und Haltbarkeit helfen Rezeptroulette beim Planen und bei Food Rescue.":"Amounts and expiry dates help Rezeptroulette plan and rescue food."}</p></div><div class="button-row">${scopeSwitch()}<button class="primary" onclick="savePantry()">${t("save")}</button></div></div><div class="panel"><div id="pantryRows" class="pantry-list">${state.pantry.map((x,i)=>pantryRow(x,i)).join("")}</div><button class="secondary" style="margin-top:10px" onclick="addPantryRow()">＋ ${state.lang==="de"?"Lebensmittel hinzufügen":"Add food"}</button></div>`;if(!state.pantry.length)addPantryRow()}catch(e){if(e.status===401){$("#main").innerHTML=`<div class="empty">${t("signInRequired")}<div style="margin-top:12px"><button class="primary" onclick="openAccount()">${t("login")}</button></div></div>`}else $("#main").innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function pantryRow(x={},i=Date.now()){const expiry=String(x.expires_at||""),days=expiry?Math.ceil((new Date(expiry)-new Date(new Date().toDateString()))/86400000):null,cls=days!==null?(days<0?"expiry-past":days<=3?"expiry-soon":""):"";return `<div class="pantry-row ${cls}" data-pantry-row><input data-p="name" placeholder="${state.lang==="de"?"Lebensmittel":"Food"}" value="${esc(x.name||"")}"><input data-p="amount" type="number" min="0" step="0.1" placeholder="Menge" value="${x.amount??""}"><select data-p="unit">${["Stück","g","kg","ml","l","EL","TL","Dose","Packung"].map(u=>`<option ${x.unit===u?"selected":""}>${u}</option>`).join("")}</select><select data-p="storage">${["Vorrat","Kühlschrank","Gefrierschrank"].map(u=>`<option ${x.storage===u?"selected":""}>${u}</option>`).join("")}</select><input data-p="expires_at" type="date" value="${esc(expiry.slice(0,10))}"><button class="danger" onclick="this.closest('[data-pantry-row]').remove()">✕</button></div>`}
function addPantryRow(){$("#pantryRows").insertAdjacentHTML("beforeend",pantryRow())}
function collectPantry(){return $$('[data-pantry-row]').map(row=>{const get=k=>row.querySelector(`[data-p="${k}"]`)?.value??"";return{name:get("name").trim(),amount:get("amount")===""?null:Number(get("amount")),unit:get("unit")||"Stück",storage:get("storage")||"Vorrat",expires_at:get("expires_at")||"",opened:false}}).filter(x=>x.name)}
async function savePantry(){const items=collectPantry();if(!state.user){state.pantry=items;localStorage.setItem("rr_guest_pantry",JSON.stringify(items));toast(t("saved"));return}try{const d=await api(`/pantry-v2?${qs({scope:scopeParam()})}`,{method:"PUT",body:JSON.stringify({items})});state.pantry=d.items||items;toast(t("saved"));renderPantry()}catch(e){toast(e.message)}}
async function renderRescue(){setView("rescue");if(!state.user){$("#main").innerHTML=`<div class="empty"><h2>Food Rescue</h2><p>${t("signInRequired")}</p><button class="primary" onclick="openAccount()">${t("login")}</button></div>`;return}$("#main").innerHTML=loading();try{const d=await api(`/food-rescue?${qs({scope:scopeParam(),limit:12})}`),recs=d.recommendations||[],exp=d.expiring||[];$("#main").innerHTML=`<div class="section-head"><div><span class="eyebrow">♻️ Food Rescue</span><h2>${state.lang==="de"?"Erst verbrauchen, statt wegwerfen":"Use it before you lose it"}</h2><p class="muted">${state.lang==="de"?"Rezepte werden nach deinem Vorrat und bald ablaufenden Lebensmitteln priorisiert.":"Recipes are prioritized using your pantry and foods expiring soon."}</p></div>${scopeSwitch()}</div>${exp.length?`<section class="panel" style="margin-bottom:16px"><h3>⏳ ${state.lang==="de"?"Bald verbrauchen":"Use soon"}</h3><div class="chips">${exp.map(x=>`<span class="chip">${esc(x.name)}${x.expires_at?` · ${esc(String(x.expires_at).slice(0,10))}`:""}</span>`).join("")}</div></section>`:""}<div class="recipe-grid">${recs.length?recs.map(x=>recipeCard(x.recipe)).join(""):`<div class="empty">${state.lang==="de"?"Noch keine passenden Vorschläge. Ergänze deinen Vorrat.":"No matching suggestions yet. Add items to your pantry."}</div>`}</div>`}catch(e){$("#main").innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function showModal(html){$("#modalContent").innerHTML=html;$("#modal").classList.remove("hidden")}
function hideModal(){$("#modal").classList.add("hidden");$("#modalContent").innerHTML=""}
function openAccount(mode="login"){if(state.user)return renderAccountModal("profile");showModal(mode==="register"?registerForm():loginForm())}
function loginForm(){return `<h2>${t("login")}</h2><form class="form-stack" onsubmit="loginUser(event)"><label class="field"><span>${t("username")} / ${t("email")}</span><input id="loginIdentifier" required autocomplete="username"></label><label class="field"><span>${t("password")}</span><input id="loginPassword" type="password" required autocomplete="current-password"></label><button class="primary">${t("login")}</button></form><button class="ghost" style="width:100%;margin-top:8px" onclick="openAccount('register')">${t("createAccount")}</button>`}
function registerForm(){return `<h2>${t("createAccount")}</h2><form class="form-stack" onsubmit="registerUser(event)"><label class="field"><span>${t("username")}</span><input id="regUsername" required minlength="3" maxlength="30"></label><label class="field"><span>${t("displayName")}</span><input id="regDisplay"></label><label class="field"><span>${t("email")}</span><input id="regEmail" type="email" required></label><label class="field"><span>${t("password")}</span><input id="regPassword" type="password" minlength="8" required></label><button class="primary">${t("createAccount")}</button></form><button class="ghost" style="width:100%;margin-top:8px" onclick="openAccount('login')">${t("login")}</button>`}
async function loginUser(e){e.preventDefault();try{state.user=await api("/auth/login",{method:"POST",body:JSON.stringify({identifier:$("#loginIdentifier").value.trim(),password:$("#loginPassword").value})});await loadAccountState();updateChrome();hideModal();toast(state.lang==="de"?"Willkommen zurück.":"Welcome back.");renderHome()}catch(err){toast(err.message)}}
async function registerUser(e){e.preventDefault();try{state.user=await api("/auth/register",{method:"POST",body:JSON.stringify({username:$("#regUsername").value.trim(),display_name:$("#regDisplay").value.trim(),email:$("#regEmail").value.trim(),password:$("#regPassword").value})});await loadAccountState();updateChrome();hideModal();toast(state.lang==="de"?"Konto erstellt.":"Account created.");renderAccountModal("food")}catch(err){toast(err.message)}}
function accountTabs(active){return `<div class="tabs"><button class="${active==="profile"?"active":""}" onclick="renderAccountModal('profile')">${t("profile")}</button><button class="${active==="food"?"active":""}" onclick="renderAccountModal('food')">${t("foodProfile")}</button><button class="${active==="house"?"active":""}" onclick="renderAccountModal('house')">${t("household")}</button><button class="${active==="security"?"active":""}" onclick="renderAccountModal('security')">${t("security")}</button></div>`}
async function renderAccountModal(tab="profile"){if(!state.user)return openAccount();showModal(`<h2>${state.lang==="de"?"Mein Bereich":"My account"}</h2>${accountTabs(tab)}<div id="accountTab">${loading()}</div>`);const el=$("#accountTab");if(tab==="profile")el.innerHTML=profileTab();if(tab==="food")await foodTab(el);if(tab==="house")await householdTab(el);if(tab==="security")await securityTab(el)}
function profileTab(){const u=state.user;return `<form class="form-stack" onsubmit="saveProfile(event)"><div class="form-grid"><label class="field"><span>${t("username")}</span><input id="profileUsername" value="${esc(u.username||"")}" required></label><label class="field"><span>${t("displayName")}</span><input id="profileDisplay" value="${esc(u.display_name||"")}"></label></div><label class="field"><span>${t("bio")}</span><textarea id="profileBio" maxlength="280">${esc(u.bio||"")}</textarea></label><button class="primary">${t("save")}</button></form><div class="panel" style="margin-top:14px"><h3>${state.lang==="de"?"Passwort ändern":"Change password"}</h3><form class="form-grid" onsubmit="changePassword(event)"><input id="currentPassword" type="password" placeholder="${t("currentPassword")}" required><input id="newPassword" type="password" minlength="8" placeholder="${t("newPassword")}" required><button class="secondary">${t("save")}</button></form></div>`}
async function saveProfile(e){e.preventDefault();try{state.user=await api("/auth/profile",{method:"PATCH",body:JSON.stringify({username:$("#profileUsername").value.trim(),display_name:$("#profileDisplay").value.trim(),bio:$("#profileBio").value.trim()})});updateChrome();toast(t("saved"))}catch(err){toast(err.message)}}
async function changePassword(e){e.preventDefault();try{await api("/auth/password",{method:"POST",body:JSON.stringify({current_password:$("#currentPassword").value,new_password:$("#newPassword").value})});toast(t("saved"));renderAccountModal("profile")}catch(err){toast(err.message)}}
async function foodTab(el){try{const d=await api("/profile/food");state.foodProfile=d.profile||{};state.allergens=d.available_allergens||state.allergens;const p=state.foodProfile;el.innerHTML=`<form onsubmit="saveFoodProfile(event)" class="form-stack"><div class="safe-note">${esc(t("allergyNotice"))}</div><div class="profile-grid"><section class="profile-section"><h3>${state.lang==="de"?"Allergien – strikt ausschließen":"Allergies – strict exclusion"}</h3><div class="check-grid">${state.allergens.map(code=>checkOption("allergy",code,allergenName(code),(p.allergies||[]).includes(code))).join("")}</div></section><section class="profile-section"><h3>${state.lang==="de"?"Unverträglichkeiten":"Intolerances"}</h3><div class="check-grid">${state.allergens.map(code=>checkOption("intolerance",code,allergenName(code),(p.intolerances||[]).includes(code))).join("")}</div></section><section class="profile-section"><h3>${state.lang==="de"?"Ernährungsweise":"Diet"}</h3><div class="check-grid">${DIETS.map(x=>checkOption("diet",x.code,x[state.lang],(p.diets||[]).includes(x.code))).join("")}</div></section><section class="profile-section"><label class="field"><span>${state.lang==="de"?"Mag ich nicht – möglichst vermeiden (eine Zutat pro Zeile)":"Dislikes – avoid where possible (one per line)"}</span><textarea id="foodDislikes">${esc((p.dislikes||[]).join("\n"))}</textarea></label><label class="field" style="margin-top:9px"><span>${state.lang==="de"?"Lieblingszutaten":"Favorite ingredients"}</span><textarea id="foodFavorites">${esc((p.favorite_ingredients||[]).join("\n"))}</textarea></label></section></div><button class="primary">${t("save")}</button></form>`}catch(e){el.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function checkOption(group,value,label,checked){return `<label class="check-row"><input type="checkbox" data-food-group="${group}" value="${esc(value)}" ${checked?"checked":""}><span>${esc(label)}</span></label>`}
function splitLines(v){return String(v||"").split(/\n|,|;/).map(x=>x.trim()).filter(Boolean)}
async function saveFoodProfile(e){e.preventDefault();const values=g=>$$(`[data-food-group="${g}"]:checked`).map(x=>x.value),payload={allergies:values("allergy"),intolerances:values("intolerance"),diets:values("diet"),dislikes:splitLines($("#foodDislikes").value),favorite_ingredients:splitLines($("#foodFavorites").value)};try{const d=await api("/profile/food",{method:"PUT",body:JSON.stringify(payload)});state.foodProfile=d.profile||payload;await refreshRecipes();toast(t("saved"));renderAccountModal("food")}catch(err){toast(err.message)}}
async function householdTab(el){try{const d=await api("/household");state.household=d?.household===undefined?d:d.household;if(!state.household){el.innerHTML=`<div class="two-col"><section class="household-card"><h3>${t("createHousehold")}</h3><form class="form-stack" onsubmit="createHousehold(event)"><input id="houseName" required maxlength="100" placeholder="${state.lang==="de"?"z. B. Familie":"e.g. Family"}"><button class="primary">${t("createHousehold")}</button></form></section><section class="household-card"><h3>${t("joinHousehold")}</h3><form class="form-stack" onsubmit="joinHousehold(event)"><input id="houseCode" required minlength="4" maxlength="16" placeholder="${t("inviteCode")}"><button class="secondary">${t("joinHousehold")}</button></form></section></div>`;return}const h=state.household,memberRows=h.members||d?.members||[];el.innerHTML=`<div class="household-card"><h3>${esc(h.name||d?.name||t("household"))}</h3>${(h.invite_code||d?.invite_code)?`<p><strong>${t("inviteCode")}:</strong> <code>${esc(h.invite_code||d.invite_code)}</code></p>`:""}${memberRows.length?`<div class="pantry-list">${memberRows.map(m=>`<div class="pantry-row" style="grid-template-columns:1fr auto"><span>${esc(m.display_name||m.username||m.name||"Mitglied")}</span><span class="pill">${esc(m.role||"")}</span></div>`).join("")}</div>`:""}<div class="button-row" style="margin-top:12px"><button class="secondary" onclick="setScope('household',false);hideModal();renderHome()">${state.lang==="de"?"Haushalt verwenden":"Use household"}</button><button class="danger" onclick="leaveHousehold()">${t("leaveHousehold")}</button></div></div>`}catch(e){el.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function createHousehold(e){e.preventDefault();try{await api("/household",{method:"POST",body:JSON.stringify({name:$("#houseName").value.trim()})});await loadAccountState();toast(t("saved"));renderAccountModal("house")}catch(err){toast(err.message)}}
async function joinHousehold(e){e.preventDefault();try{await api("/household/join",{method:"POST",body:JSON.stringify({invite_code:$("#houseCode").value.trim()})});await loadAccountState();toast(t("saved"));renderAccountModal("house")}catch(err){toast(err.message)}}
async function leaveHousehold(){if(!confirm(state.lang==="de"?"Haushalt wirklich verlassen?":"Leave household?"))return;try{await api("/household",{method:"DELETE"});state.scope="personal";localStorage.setItem("rr_scope","personal");await loadAccountState();renderAccountModal("house")}catch(e){toast(e.message)}}
async function securityTab(el){let sessions=[];try{const d=await api("/auth/sessions");sessions=normalizeList(d)}catch{}el.innerHTML=`<section class="profile-section"><h3>${t("sessions")}</h3>${sessions.length?sessions.map(s=>`<div class="session-row"><strong>${esc(s.device||s.user_agent||state.lang==="de"?"Sitzung":"Session")}</strong><div class="hint">${esc(s.created_at||"")} ${s.expires_at?`· ${esc(s.expires_at)}`:""}</div></div>`).join(""):`<div class="hint">${state.lang==="de"?"Keine Sitzungsdetails verfügbar.":"No session details available."}</div>`}</section><div class="button-row" style="margin-top:14px"><button class="secondary" onclick="exportData()">${t("exportData")}</button><button class="secondary" onclick="logoutAll()">${t("logoutAll")}</button><button class="secondary" onclick="logoutUser()">${t("logout")}</button><button class="danger" onclick="deleteAccount()">${t("deleteAccount")}</button></div>`}
async function exportData(){try{const d=await api("/auth/export");const blob=new Blob([JSON.stringify(d,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="rezeptroulette-export.json";a.click();URL.revokeObjectURL(url)}catch(e){toast(e.message)}}
async function logoutUser(){try{await api("/auth/logout",{method:"POST"})}catch{}state.user=null;state.foodProfile=null;state.household=null;state.scope="personal";localStorage.setItem("rr_scope","personal");hideModal();updateChrome();renderHome()}
async function logoutAll(){if(!confirm(t("logoutAll")+"?"))return;try{await api("/auth/logout-all",{method:"POST"})}catch{}state.user=null;state.scope="personal";hideModal();updateChrome();renderHome()}
async function deleteAccount(){if(!confirm(state.lang==="de"?"Konto und persönliche Daten wirklich dauerhaft löschen?":"Permanently delete your account and personal data?"))return;try{await api("/auth/account",{method:"DELETE"});state.user=null;state.scope="personal";hideModal();updateChrome();renderHome()}catch(e){toast(e.message)}}
function openCreateRecipe(){showModal(`<h2>${state.lang==="de"?"Eigenes Rezept":"My recipe"}</h2><form class="form-stack" onsubmit="createRecipe(event)"><label class="field"><span>Name</span><input id="ownName" required></label><div class="form-grid"><label class="field"><span>${state.lang==="de"?"Küche":"Cuisine"}</span><input id="ownCuisine" value="Eigene Küche"></label><label class="field"><span>${state.lang==="de"?"Kochzeit (Min)":"Cooking time (min)"}</span><input id="ownTime" type="number" min="1" value="30"></label><label class="field"><span>${t("servings")}</span><input id="ownServings" type="number" min="1" value="2"></label><label class="field"><span>${state.lang==="de"?"Schwierigkeit":"Difficulty"}</span><select id="ownDifficulty"><option>Einfach</option><option>Mittel</option><option>Schwer</option></select></label></div><label class="field"><span>${state.lang==="de"?"Beschreibung":"Description"}</span><textarea id="ownDescription"></textarea></label><label class="field"><span>${t("ingredients")} – ${state.lang==="de"?"eine pro Zeile":"one per line"}</span><textarea id="ownIngredients" required></textarea></label><label class="field"><span>${t("instructions")} – ${state.lang==="de"?"ein Schritt pro Zeile":"one step per line"}</span><textarea id="ownSteps" required></textarea></label><button class="primary">${t("save")}</button></form>`)}
async function createRecipe(e){e.preventDefault();const steps=splitLines($("#ownSteps").value),payload={name:$("#ownName").value.trim(),kueche:$("#ownCuisine").value.trim(),kochzeit:Number($("#ownTime").value),portionen:Number($("#ownServings").value),schwierigkeit:$("#ownDifficulty").value,description:$("#ownDescription").value.trim(),tags:["Eigenes Rezept"],zutaten:splitLines($("#ownIngredients").value),anleitung:steps.map((x,i)=>`${i+1}. ${x}`).join("\n")};try{const r=await api("/rezept-erstellen",{method:"POST",body:JSON.stringify(payload)});hideModal();await refreshRecipes();openRecipe(r.id||r.recipe_id)}catch(err){toast(err.message)}}
function isIOS(){return /iphone|ipad|ipod/i.test(navigator.userAgent)&&!window.MSStream}
async function installApp(){if(state.installPrompt){state.installPrompt.prompt();await state.installPrompt.userChoice;state.installPrompt=null;$("#installBtn").classList.add("hidden");renderCurrent()}else if(isIOS()){alert(state.lang==="de"?"In Safari: Teilen → Zum Home-Bildschirm.":"In Safari: Share → Add to Home Screen.")}}
function setupPWA(){window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();state.installPrompt=e;$("#installBtn").classList.remove("hidden");if(state.view==="home")renderHome()});window.addEventListener("appinstalled",()=>{state.installPrompt=null;$("#installBtn").classList.add("hidden")});if("serviceWorker" in navigator)navigator.serviceWorker.register("/static/service-worker.js").catch(()=>{})}
function bind(){$$('[data-nav]').forEach(b=>b.addEventListener("click",()=>route(b.dataset.nav)));$("#accountBtn").addEventListener("click",()=>openAccount());$("#themeBtn").addEventListener("click",async()=>{document.body.classList.toggle("dark");const theme=document.body.classList.contains("dark")?"dark":"light";localStorage.setItem("rr_theme",theme);updateChrome();if(state.user)api("/preferences",{method:"PUT",body:JSON.stringify({preferences:{theme}})}).catch(()=>{})});$("#languageBtn").addEventListener("click",()=>{state.lang=state.lang==="de"?"en":"de";localStorage.setItem("rr_lang",state.lang);updateChrome();renderCurrent()});$("#installBtn").addEventListener("click",installApp);$("#modalClose").addEventListener("click",hideModal);$("#modal").addEventListener("click",e=>{if(e.target===$("#modal"))hideModal()});$("#cookClose").addEventListener("click",closeCook);$("#cookPrev").addEventListener("click",()=>{if(state.cookIndex>0){state.cookIndex--;renderCookStep()}});$("#cookNext").addEventListener("click",()=>{if(state.cookIndex<state.cookSteps.length-1){state.cookIndex++;renderCookStep()}else closeCook()});$$('[data-action="home"]').forEach(b=>b.addEventListener("click",()=>route("home")))}
async function bootstrap(){if(localStorage.getItem("rr_theme")==="dark")document.body.classList.add("dark");bind();setupPWA();updateChrome();await Promise.all([initAuth(),refreshRecipes().catch(()=>[])]);updateChrome();const view=new URLSearchParams(location.search).get("view");route(["home","recipes","roulette","plan","shopping","pantry","rescue"].includes(view)?view:"home")}
window.route=route;window.setScope=setScope;window.renderRecipes=renderRecipes;window.openRecipe=openRecipe;window.filterRecipes=filterRecipes;window.toggleFavorite=toggleFavorite;window.setRating=setRating;window.markEaten=markEaten;window.startCookMode=startCookMode;window.drawRoulette=drawRoulette;window.autoPlan=autoPlan;window.resetPlan=resetPlan;window.setPlanSlot=setPlanSlot;window.quickPlan=quickPlan;window.submitQuickPlan=submitQuickPlan;window.renderPlan=renderPlan;window.toggleShoppingCheck=toggleShoppingCheck;window.copyShopping=copyShopping;window.addPantryRow=addPantryRow;window.savePantry=savePantry;window.openAccount=openAccount;window.renderAccountModal=renderAccountModal;window.loginUser=loginUser;window.registerUser=registerUser;window.saveProfile=saveProfile;window.changePassword=changePassword;window.saveFoodProfile=saveFoodProfile;window.createHousehold=createHousehold;window.joinHousehold=joinHousehold;window.leaveHousehold=leaveHousehold;window.exportData=exportData;window.logoutUser=logoutUser;window.logoutAll=logoutAll;window.deleteAccount=deleteAccount;window.openCreateRecipe=openCreateRecipe;window.createRecipe=createRecipe;window.saveRecipeNote=saveRecipeNote;window.installApp=installApp;
bootstrap();
